<?php

/**
 * Definiciones de las vistas, tomadas del motor con SHOW CREATE VIEW.
 * Generado por bin/regenerar-vistas.php — NO editar a mano.
 * Las usa FuenteVistas para inlinearlas y no depender de CREATE VIEW
 * (hostings gratis lo bloquean). Fidelidad: es la definicion exacta.
 */

return array (
  'v_amortizacion' => 'select `q`.`id` AS `id`,`q`.`credito_id` AS `credito_id`,`q`.`numero` AS `numero`,`q`.`capital_cent` AS `capital_cent`,`q`.`interes_cent` AS `interes_cent`,`q`.`mora_cent` AS `mora_cent`,`q`.`total_cent` AS `total_cent`,`q`.`pagado_cent` AS `pagado_cent`,`q`.`total_cent` - `q`.`pagado_cent` AS `pendiente_cent`,`q`.`fecha_vencimiento` AS `fecha_vencimiento`,`q`.`estado` AS `estado`,`q`.`pagada_en` AS `pagada_en`,`q`.`pagada_tarde` AS `pagada_tarde`,to_days(curdate()) - to_days(`q`.`fecha_vencimiento`) AS `dias_vencida`,`cr`.`folio` AS `credito_folio`,`cr`.`usuario_id` AS `usuario_id`,concat(`u`.`nombres`,\' \',`u`.`apellidos`) AS `cliente`,`p`.`nombre` AS `producto` from (((`cuotas` `q` join `creditos` `cr` on(`cr`.`id` = `q`.`credito_id`)) join `usuarios` `u` on(`u`.`id` = `cr`.`usuario_id`)) join `productos` `p` on(`p`.`id` = `cr`.`producto_id`))',
  'v_asientos_descuadrados' => 'select `a`.`id` AS `id`,`a`.`uuid` AS `uuid`,`a`.`referencia` AS `referencia`,`a`.`tipo` AS `tipo`,sum(`m`.`importe_cent`) AS `descuadre_cent` from (`asientos` `a` join `movimientos` `m` on(`m`.`asiento_id` = `a`.`id`)) group by `a`.`id`,`a`.`uuid`,`a`.`referencia`,`a`.`tipo` having sum(`m`.`importe_cent`) <> 0',
  'v_balance_general' => 'select sum(case when `cuentas`.`es_tecnica` = 0 then `cuentas`.`saldo_cent` else 0 end) AS `total_clientes_cent`,sum(case when `cuentas`.`es_tecnica` = 1 then `cuentas`.`saldo_cent` else 0 end) AS `total_tecnicas_cent`,sum(`cuentas`.`saldo_cent`) AS `descuadre_cent` from `cuentas`',
  'v_bandeja_entrada' => 'select `m`.`id` AS `id`,`m`.`uuid` AS `uuid`,`m`.`destinatario_id` AS `destinatario_id`,`m`.`asunto` AS `asunto`,left(`m`.`cuerpo`,180) AS `extracto`,`m`.`leido_en` AS `leido_en`,`m`.`creado_en` AS `creado_en`,`u`.`usuario` AS `remitente_usuario`,concat(`u`.`nombres`,\' \',`u`.`apellidos`) AS `remitente`,`u`.`foto_perfil` AS `remitente_foto` from (`mensajes` `m` join `usuarios` `u` on(`u`.`id` = `m`.`remitente_id`)) where `m`.`archivado_dest` = 0',
  'v_cartera_morosa' => 'select `u`.`id` AS `usuario_id`,`u`.`uuid` AS `usuario_uuid`,concat(`u`.`nombres`,\' \',`u`.`apellidos`) AS `cliente`,`u`.`correo` AS `correo`,`u`.`telefono` AS `telefono`,`cr`.`id` AS `credito_id`,`cr`.`uuid` AS `credito_uuid`,`cr`.`clasificacion` AS `clasificacion`,count(`q`.`id`) AS `cuotas_vencidas`,sum(`q`.`total_cent` - `q`.`pagado_cent`) AS `deuda_vencida_cent`,sum(`q`.`mora_cent`) AS `mora_acumulada_cent`,min(`q`.`fecha_vencimiento`) AS `vencimiento_mas_antiguo`,to_days(curdate()) - to_days(min(`q`.`fecha_vencimiento`)) AS `dias_mora_max`,case when to_days(curdate()) - to_days(min(`q`.`fecha_vencimiento`)) <= 30 then \'A\' when to_days(curdate()) - to_days(min(`q`.`fecha_vencimiento`)) <= 60 then \'B\' when to_days(curdate()) - to_days(min(`q`.`fecha_vencimiento`)) <= 90 then \'C\' when to_days(curdate()) - to_days(min(`q`.`fecha_vencimiento`)) <= 180 then \'D\' else \'E\' end AS `clasificacion_sugerida` from ((`usuarios` `u` join `creditos` `cr` on(`cr`.`usuario_id` = `u`.`id` and `cr`.`estado` = \'vigente\')) join `cuotas` `q` on(`q`.`credito_id` = `cr`.`id`)) where `q`.`estado` in (\'pendiente\',\'parcial\',\'vencida\') and `q`.`fecha_vencimiento` < curdate() group by `u`.`id`,`u`.`uuid`,`u`.`nombres`,`u`.`apellidos`,`u`.`correo`,`u`.`telefono`,`cr`.`id`,`cr`.`uuid`,`cr`.`clasificacion`',
  'v_conciliacion_saldos' => 'select `c`.`id` AS `cuenta_id`,`c`.`numero_cuenta` AS `numero_cuenta`,`c`.`es_tecnica` AS `es_tecnica`,`c`.`saldo_cent` AS `saldo_proyectado_cent`,coalesce(sum(`m`.`importe_cent`),0) AS `saldo_libro_cent`,`c`.`saldo_cent` - coalesce(sum(`m`.`importe_cent`),0) AS `diferencia_cent` from (`cuentas` `c` left join `movimientos` `m` on(`m`.`cuenta_id` = `c`.`id`)) group by `c`.`id`,`c`.`numero_cuenta`,`c`.`es_tecnica`,`c`.`saldo_cent`',
  'v_expediente_cliente' => 'select `u`.`id` AS `usuario_id`,`u`.`uuid` AS `uuid`,`u`.`usuario` AS `usuario`,`u`.`correo` AS `correo`,`u`.`nombres` AS `nombres`,`u`.`apellidos` AS `apellidos`,`u`.`estado` AS `estado`,`u`.`foto_perfil` AS `foto_perfil`,`u`.`creado_en` AS `registrado_en`,`u`.`ultimo_acceso_en` AS `ultimo_acceso_en`,`d`.`dui` AS `dui`,`d`.`nit` AS `nit`,`d`.`telefono` AS `telefono`,`d`.`celular` AS `celular`,`d`.`direccion` AS `direccion`,`d`.`empresa` AS `empresa`,`d`.`cargo` AS `cargo`,`d`.`fecha_nacimiento` AS `fecha_nacimiento`,`d`.`genero` AS `genero`,`d`.`estado_civil` AS `estado_civil`,`d`.`ingreso_mensual_cent` AS `ingreso_mensual_cent`,`d`.`perfil_completo` AS `perfil_completo`,(select count(0) from `cuentas` `c` where `c`.`usuario_id` = `u`.`id` and `c`.`es_tecnica` = 0) AS `cuentas`,(select coalesce(sum(`cuentas`.`saldo_cent`),0) from `cuentas` where `cuentas`.`usuario_id` = `u`.`id` and `cuentas`.`es_tecnica` = 0) AS `saldo_total_cent`,(select count(0) from `tarjetas` `t` where `t`.`usuario_id` = `u`.`id` and `t`.`estado` <> \'cancelada\') AS `tarjetas`,(select count(0) from `creditos` `cr` where `cr`.`usuario_id` = `u`.`id` and `cr`.`estado` = \'vigente\') AS `creditos_vigentes`,(select coalesce(sum(`creditos`.`saldo_capital_cent`),0) from `creditos` where `creditos`.`usuario_id` = `u`.`id` and `creditos`.`estado` = \'vigente\') AS `deuda_cent` from (`usuarios` `u` left join `detalle_usuarios` `d` on(`d`.`usuario_id` = `u`.`id`)) where `u`.`rol_id` = 5',
  'v_expediente_documentos' => 'select `d`.`id` AS `id`,`d`.`uuid` AS `uuid`,`d`.`usuario_id` AS `usuario_id`,`d`.`tipo` AS `tipo`,`d`.`nombre_archivo` AS `nombre_archivo`,`d`.`mime` AS `mime`,`d`.`tamano_bytes` AS `tamano_bytes`,`d`.`hash_sha256` AS `hash_sha256`,`d`.`verificado` AS `verificado`,`d`.`creado_en` AS `creado_en`,concat(`u`.`nombres`,\' \',`u`.`apellidos`) AS `titular`,concat(`s`.`nombres`,\' \',`s`.`apellidos`) AS `subido_por_nombre`,concat(`v`.`nombres`,\' \',`v`.`apellidos`) AS `verificado_por_nombre`,(select count(0) from `documento_accesos` `a` where `a`.`documento_id` = `d`.`id`) AS `veces_visto` from (((`documentos` `d` join `usuarios` `u` on(`u`.`id` = `d`.`usuario_id`)) join `usuarios` `s` on(`s`.`id` = `d`.`subido_por`)) left join `usuarios` `v` on(`v`.`id` = `d`.`verificado_por`))',
  'v_indicadores_institucion' => 'select (select count(0) from `usuarios` where `usuarios`.`rol_id` = 5 and `usuarios`.`estado` = \'activo\') AS `clientes_activos`,(select count(0) from `cuentas` where `cuentas`.`estado` = \'activa\' and `cuentas`.`es_tecnica` = 0) AS `cuentas_activas`,(select coalesce(sum(`cuentas`.`saldo_cent`),0) from `cuentas` where `cuentas`.`es_tecnica` = 0) AS `captaciones_cent`,(select count(0) from `creditos` where `creditos`.`estado` = \'vigente\') AS `creditos_vigentes`,(select coalesce(sum(`creditos`.`saldo_capital_cent`),0) from `creditos` where `creditos`.`estado` = \'vigente\') AS `cartera_cent`,(select count(0) from `tarjetas` where `tarjetas`.`estado` = \'activa\') AS `tarjetas_activas`,(select coalesce(sum(`tarjetas`.`saldo_usado_cent`),0) from `tarjetas` where `tarjetas`.`estado` = \'activa\') AS `saldo_tarjetas_cent`,(select count(0) from `solicitudes_credito` where `solicitudes_credito`.`etapa` not in (\'aprobada\',\'rechazada\',\'desembolsada\')) AS `solicitudes_pendientes`,(select count(0) from `tickets` where `tickets`.`estado` <> \'cerrado\') AS `tickets_abiertos`,(select count(0) from `asientos` where cast(`asientos`.`creado_en` as date) = curdate()) AS `operaciones_hoy`,(select count(distinct `v_cartera_morosa`.`usuario_id`) from `v_cartera_morosa`) AS `clientes_mora`,(select coalesce(sum(`v_cartera_morosa`.`deuda_vencida_cent`),0) from `v_cartera_morosa`) AS `mora_cent`',
  'v_pasarela_conciliacion' => 'select (select coalesce(sum(`pagos_pasarela`.`importe_cent`),0) from `pagos_pasarela` where `pagos_pasarela`.`estado` = \'cobrado\') AS `cobrado_cent`,(select coalesce(sum(`pagos_pasarela`.`importe_cent`),0) from `pagos_pasarela` where `pagos_pasarela`.`estado` = \'devuelto\') AS `devuelto_cent`,(select coalesce(sum(`pagos_pasarela`.`importe_cent`),0) from `pagos_pasarela` where `pagos_pasarela`.`estado` in (\'iniciado\',\'procesando\')) AS `en_curso_cent`,(select count(0) from `pagos_pasarela` where `pagos_pasarela`.`estado` = \'fallido\') AS `fallidos`,(select coalesce(`cuentas`.`saldo_cent`,0) from `cuentas` where `cuentas`.`numero_cuenta` = \'0000000001\') AS `saldo_tecnica_cent`',
  'v_planes_diferidos' => 'select `p`.`id` AS `id`,`p`.`uuid` AS `uuid`,`p`.`folio` AS `folio`,`p`.`tarjeta_id` AS `tarjeta_id`,`p`.`movimiento_id` AS `movimiento_id`,`p`.`tipo` AS `tipo`,`p`.`monto_cent` AS `monto_cent`,`p`.`interes_total_cent` AS `interes_total_cent`,`p`.`total_cent` AS `total_cent`,`p`.`pagado_cent` AS `pagado_cent`,`p`.`cuotas` AS `cuotas`,`p`.`cuotas_pagadas` AS `cuotas_pagadas`,`p`.`cuota_cent` AS `cuota_cent`,`p`.`tasa_bp` AS `tasa_bp`,`p`.`comercio` AS `comercio`,`p`.`estado` AS `estado`,`p`.`creado_en` AS `creado_en`,`p`.`liquidado_en` AS `liquidado_en`,`t`.`ultimos4` AS `ultimos4`,`t`.`marca` AS `marca`,`t`.`usuario_id` AS `usuario_id`,`p`.`total_cent` - `p`.`pagado_cent` AS `pendiente_cent`,(select min(`c`.`fecha_corte`) from `tarjeta_plan_cuotas` `c` where `c`.`plan_id` = `p`.`id` and `c`.`estado` = \'pendiente\') AS `proxima_cuota`,`p`.`cuotas` - `p`.`cuotas_pagadas` AS `cuotas_restantes` from (`tarjeta_planes` `p` join `tarjetas` `t` on(`t`.`id` = `p`.`tarjeta_id`))',
  'v_referencias_expediente' => 'select `r`.`id` AS `id`,`r`.`usuario_id` AS `usuario_id`,`r`.`tipo` AS `tipo`,`r`.`nombres` AS `nombres`,`r`.`apellidos` AS `apellidos`,concat(`r`.`nombres`,\' \',`r`.`apellidos`) AS `nombre_completo`,`r`.`empresa` AS `empresa`,`r`.`profesion` AS `profesion`,`r`.`telefono` AS `telefono`,`r`.`celular` AS `celular`,`r`.`correo` AS `correo`,`r`.`direccion` AS `direccion`,`r`.`parentesco` AS `parentesco`,`r`.`anios_conocer` AS `anios_conocer`,`r`.`verificada` AS `verificada`,`r`.`verificada_en` AS `verificada_en`,`r`.`notas` AS `notas`,`r`.`creado_en` AS `creado_en`,concat(`v`.`nombres`,\' \',`v`.`apellidos`) AS `verificador`,`r`.`solicitud_id` AS `solicitud_id`,`r`.`credito_id` AS `credito_id`,`s`.`folio` AS `solicitud_folio`,`c`.`folio` AS `credito_folio` from (((`referencias` `r` left join `usuarios` `v` on(`v`.`id` = `r`.`verificada_por`)) left join `solicitudes_credito` `s` on(`s`.`id` = `r`.`solicitud_id`)) left join `creditos` `c` on(`c`.`id` = `r`.`credito_id`))',
  'v_resumen_cliente' => 'select `u`.`id` AS `usuario_id`,`u`.`uuid` AS `uuid`,concat(`u`.`nombres`,\' \',`u`.`apellidos`) AS `nombre_completo`,(select coalesce(sum(`cuentas`.`saldo_cent`),0) from `cuentas` where `cuentas`.`usuario_id` = `u`.`id` and `cuentas`.`estado` = \'activa\') AS `total_ahorros_cent`,(select count(0) from `cuentas` where `cuentas`.`usuario_id` = `u`.`id` and `cuentas`.`estado` = \'activa\') AS `cuentas_activas`,(select count(0) from `tarjetas` where `tarjetas`.`usuario_id` = `u`.`id` and `tarjetas`.`estado` = \'activa\') AS `tarjetas_activas`,(select coalesce(sum(`tarjetas`.`saldo_usado_cent`),0) from `tarjetas` where `tarjetas`.`usuario_id` = `u`.`id` and `tarjetas`.`estado` = \'activa\') AS `deuda_tarjetas_cent`,(select coalesce(sum(`creditos`.`saldo_capital_cent`),0) from `creditos` where `creditos`.`usuario_id` = `u`.`id` and `creditos`.`estado` = \'vigente\') AS `deuda_creditos_cent`,(select count(0) from `notificaciones` where `notificaciones`.`usuario_id` = `u`.`id` and `notificaciones`.`leida_en` is null) AS `notificaciones_sin_leer` from `usuarios` `u`',
  'v_tarjetas_detalle' => 'select `t`.`id` AS `id`,`t`.`uuid` AS `uuid`,`t`.`usuario_id` AS `usuario_id`,`t`.`ultimos4` AS `ultimos4`,`t`.`bin6` AS `bin6`,`t`.`marca` AS `marca`,`t`.`tipo` AS `tipo`,`t`.`titular` AS `titular`,`t`.`alias` AS `alias`,`t`.`expira_mes` AS `expira_mes`,`t`.`expira_anio` AS `expira_anio`,`t`.`estado` AS `estado`,`t`.`limite_cent` AS `limite_cent`,`t`.`saldo_usado_cent` AS `saldo_usado_cent`,`t`.`limite_diario_cent` AS `limite_diario_cent`,`t`.`dia_corte` AS `dia_corte`,`t`.`dias_para_pago` AS `dias_para_pago`,`t`.`tasa_diferido_bp` AS `tasa_diferido_bp`,`t`.`compras_internet` AS `compras_internet`,`t`.`compras_exterior` AS `compras_exterior`,`t`.`contactless` AS `contactless`,`t`.`congelada_hasta` AS `congelada_hasta`,`t`.`proximo_corte` AS `proximo_corte`,`t`.`emitida_en` AS `emitida_en`,`t`.`producto_id` AS `producto_id`,`t`.`cuenta_id` AS `cuenta_id`,`t`.`sobregiro_permitido` AS `sobregiro_permitido`,`t`.`sobregiro_tolerancia_bp` AS `sobregiro_tolerancia_bp`,`t`.`pago_automatico` AS `pago_automatico`,`t`.`pago_automatico_cuenta_id` AS `pago_automatico_cuenta_id`,`t`.`alerta_consumo_cent` AS `alerta_consumo_cent`,case when `t`.`sobregiro_permitido` = 1 then round(`t`.`limite_cent` * `t`.`sobregiro_tolerancia_bp` / 10000,0) else 0 end AS `sobregiro_cent`,greatest(0,`t`.`limite_cent` - `t`.`saldo_usado_cent`) AS `disponible_cent`,case when `t`.`limite_cent` > 0 then least(100,round(`t`.`saldo_usado_cent` * 100.0 / `t`.`limite_cent`,1)) else 0 end AS `uso_pct`,concat(`u`.`nombres`,\' \',`u`.`apellidos`) AS `propietario`,`u`.`correo` AS `propietario_correo`,`u`.`nombres` AS `nombres`,`u`.`apellidos` AS `apellidos`,`pr`.`nivel` AS `producto_nivel`,`pr`.`codigo` AS `producto_codigo`,`pr`.`nombre` AS `producto_nombre`,`cu`.`numero_cuenta` AS `cuenta_numero`,`cu`.`saldo_cent` AS `cuenta_saldo_cent`,(select count(0) from `tarjeta_planes` `p` where `p`.`tarjeta_id` = `t`.`id` and `p`.`estado` = \'vigente\') AS `planes_vigentes`,(select coalesce(sum(`p`.`total_cent` - `p`.`pagado_cent`),0) from `tarjeta_planes` `p` where `p`.`tarjeta_id` = `t`.`id` and `p`.`estado` = \'vigente\') AS `saldo_diferido_cent`,(select count(0) from `tarjeta_movimientos` `m` where `m`.`tarjeta_id` = `t`.`id` and `m`.`tipo` = \'consumo\' and `m`.`plan_id` is null and `m`.`diferible` = 1 and `m`.`creado_en` > current_timestamp() - interval 90 day) AS `consumos_diferibles` from (((`tarjetas` `t` join `usuarios` `u` on(`u`.`id` = `t`.`usuario_id`)) left join `productos` `pr` on(`pr`.`id` = `t`.`producto_id`)) left join `cuentas` `cu` on(`cu`.`id` = `t`.`cuenta_id`))',
  'v_tickets_abiertos' => 'select `t`.`id` AS `id`,`t`.`uuid` AS `uuid`,`t`.`folio` AS `folio`,`t`.`usuario_id` AS `usuario_id`,`t`.`asignado_a` AS `asignado_a`,`t`.`categoria` AS `categoria`,`t`.`prioridad` AS `prioridad`,`t`.`titulo` AS `titulo`,`t`.`descripcion` AS `descripcion`,`t`.`estado` AS `estado`,`t`.`resolucion` AS `resolucion`,`t`.`creado_en` AS `creado_en`,`t`.`ultima_actividad` AS `ultima_actividad`,`t`.`cerrado_en` AS `cerrado_en`,concat(`u`.`nombres`,\' \',`u`.`apellidos`) AS `solicitante`,`u`.`correo` AS `solicitante_correo`,concat(`a`.`nombres`,\' \',`a`.`apellidos`) AS `responsable`,timestampdiff(HOUR,`t`.`creado_en`,current_timestamp()) AS `horas_abierto`,(select count(0) from `ticket_respuestas` `r` where `r`.`ticket_id` = `t`.`id`) AS `respuestas` from ((`tickets` `t` join `usuarios` `u` on(`u`.`id` = `t`.`usuario_id`)) left join `usuarios` `a` on(`a`.`id` = `t`.`asignado_a`)) where `t`.`estado` <> \'cerrado\'',
);
